export default pattern<
  IframeFirebreakCommonsInput,
  IframeFirebreakCommonsOutput
>(({
  input,
  output,
}) => {
  const state = new Writable<IframeStateData>(DEFAULT_STATE);
  const iframeInput = input ?? DEFAULT_INPUT;
  const context = IframeContext({
    input: iframeInput,
    state,
    output,
  });

  return {
    [NAME]: "Firebreak Commons",
    [UI]: (
      <div style={{ width: "100%", height: "100vh" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
